</head>
<body>
<main>
  <header>
    <p class="kicker">Cellular automaton · B3/S23</p>
    <h1>Game of <em>Life</em></h1>
    <p class="sub">Draw cells with your pointer, then watch the universe argue with itself.</p>
  </header>

  <div class="toolbar">
    <div class="stats">
      <div class="stat"><span class="label">Generation</span><span class="value" id="gen-val">0</span></div>
      <div class="stat"><span class="label">Population</span><span class="value mint" id="pop-val">0</span></div>
    </div>
    <div class="speedbox">
      <span>Tempo</span>
      <input id="speed" type="range" min="0" max="100" value="62" aria-label="simulation speed"/>
    </div>
  </div>

  <div class="board" id="board">
    <canvas id="life"></canvas>
    <div class="hint" id="hint">
      <strong>The void awaits.</strong>
      <span>Drag on the grid to draw living cells —<br/>or press <kbd>R</kbd> for a bowl of primordial soup.</span>
    </div>
  </div>

  <div class="controls">
    <button id="step" class="btn" title="Advance one generation (S)">
      <svg viewBox="0 0 24 24" width="15" height="15" fill="currentColor"><path d="M6 5.5v13L16.2 12zM17.6 5.5h2.3v13h-2.3z"/></svg>
      Step
    </button>
    <button id="play" class="btn primary" aria-pressed="false" title="Toggle auto-run (Space)">
      <svg id="icon-play" viewBox="0 0 24 24" width="15" height="15" fill="currentColor"><path d="M8 5.2v13.6L19 12z"/></svg>
      <svg id="icon-pause" viewBox="0 0 24 24" width="15" height="15" fill="currentColor" style="display:none"><path d="M7 5h3.4v14H7zM13.6 5H17v14h-3.6z"/></svg>
      <span id="play-label">Run</span>
    </button>
    <button id="random" class="btn" title="Seed random cells (R)">
      <svg viewBox="0 0 24 24" width="15" height="15">
        <rect x="3.2" y="3.2" width="17.6" height="17.6" rx="4.5" fill="none" stroke="currentColor" stroke-width="1.8"/>
        <g fill="currentColor"><circle cx="8.3" cy="8.3" r="1.5"/><circle cx="15.7" cy="8.3" r="1.5"/><circle cx="12" cy="12" r="1.5"/><circle cx="8.3" cy="15.7" r="1.5"/><circle cx="15.7" cy="15.7" r="1.5"/></g>
      </svg>
      Random
    </button>
    <button id="clear" class="btn" title="Kill all cells (C)">
      <svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">
        <path d="M4.5 7h15"/>
        <path d="M9.5 7V5.2A1.2 1.2 0 0 1 10.7 4h2.6a1.2 1.2 0 0 1 1.2 1.2V7"/>
        <path d="M6.5 7l.9 11.4A2 2 0 0 0 9.4 20h5.2a2 2 0 0 0 2-1.6L17.5 7"/>
        <path d="M10 11v5M14 11v5"/>
      </svg>
      Clear
    </button>
  </div>

  <div class="stamps">
    <span class="lbl">Try</span>
    <button class="chip" data-stamp="Glider">Glider</button>
    <button class="chip" data-stamp="Spaceship">Spaceship</button>
    <button class="chip" data-stamp="Pulsar">Pulsar</button>
    <button class="chip" data-stamp="Acorn">Acorn</button>
  </div>

  <footer>
    <kbd>Space</kbd> run/pause &nbsp;·&nbsp; <kbd>S</kbd> step &nbsp;·&nbsp; <kbd>R</kbd> random &nbsp;·&nbsp; <kbd>C</kbd> clear<br/>
    48 × 48 universe · dead edges · simultaneous generations
  </footer>
</main>

<script>
(() => {
'use strict';

/* ---------- constants & state ---------- */
const N = 48, CELL = 12, SIZE = N * CELL, PW = N + 2;   // padded grid: dead border ring
const canvas = document.getElementById('life');
const ctx = canvas.getContext('2d');
const DPR = Math.min(window.devicePixelRatio || 1, 2);
canvas.width = SIZE * DPR;
canvas.height = SIZE * DPR;
canvas.style.width = SIZE + 'px';
canvas.style.height = SIZE + 'px';
ctx.setTransform(DPR, 0, 0, DPR, 0, 0);

let cur = new Uint8Array(PW * (N + 2));   // current generation (padded, border always dead)
let nxt = new Uint8Array(PW * (N + 2));   // scratch buffer for simultaneous update
const age = new Uint16Array(N * N);       // how long each cell has been alive
const ghost = new Float32Array(N * N);    // fading trails where cells just died

let gen = 0;
let needsDraw = true;
let playing = false, lastStepT = 0;
let painting = false, paintVal = 1, lastCell = null, hover = null;

/* ---------- DOM ---------- */
const $ = id => document.getElementById(id);
const genVal = $('gen-val'), popVal = $('pop-val'), speed = $('speed'),
      hint = $('hint'), board = $('board'), playBtn = $('play'),
      iconPlay = $('icon-play'), iconPause = $('icon-pause'), playLbl = $('play-label');

/* ---------- colour: newborns flare gold, elders settle into teal-green ---------- */
const AGEMAX = 18, PAL = [];
for (let a = 1; a <= AGEMAX; a++) {
  const t = (a - 1) / (AGEMAX - 1);
  PAL.push(`hsl(${(54 + t * 111) | 0} ${(96 - t * 26) | 0}% ${(64 - t * 9) | 0}%)`);
}
const cellColor = a => PAL[Math.min(a, AGEMAX) - 1];

const gcache = {};
const ghostColor = g => {
  const q = (Math.round(g * 25) / 25).toFixed(2);
  return gcache[q] || (gcache[q] = `rgba(61,220,151,${q * 0.33})`);
};

/* ---------- core simulation ---------- */
function advance() {
  for (let y = 0; y < N; y++) {
    let r = (y + 1) * PW + 1;
    for (let x = 0; x < N; x++, r++) {
      const n = cur[r - 1] + cur[r + 1] + cur[r - PW] + cur[r + PW]
              + cur[r - PW - 1] + cur[r - PW + 1] + cur[r + PW - 1] + cur[r + PW + 1];
      const a = cur[r];
      const v = a ? (n === 2 || n === 3) : (n === 3);   // B3/S23
      nxt[r] = v ? 1 : 0;
      const gi = y * N + x;
      if (v)      { age[gi] = a ? age[gi] + 1 : 1; }
      else if (a) { ghost[gi] = 1; age[gi] = 0; }
    }
  }
  const t = cur; cur = nxt; nxt = t;   // atomic swap => perfectly simultaneous
  gen++;
  needsDraw = true;
  updateStats();
}

function clearBoard() {
  cur.fill(0); nxt.fill(0); age.fill(0); ghost.fill(0);
  gen = 0;
  needsDraw = true;
  updateStats();
}

function randomize() {
  for (let y = 0; y < N; y++) {
    const r = (y + 1) * PW + 1;
    for (let x = 0; x < N; x++) {
      const v = Math.random() < 0.28 ? 1 : 0;
      cur[r + x] = v;
      age[y * N + x] = v;
    }
  }
  ghost.fill(0);
  gen = 0;
  needsDraw = true;
  updateStats();
}

function setCell(x, y, v) {
  if (x < 0 || y < 0 || x >= N || y >= N) return;
  const p = (y + 1) * PW + (x + 1), gi = y * N + x;
  if (v) { if (!cur[p]) { cur[p] = 1; age[gi] = 1; } }
  else if (cur[p]) { cur[p] = 0; age[gi] = 0; ghost[gi] = 1; }
  needsDraw = true;
}

/* ---------- rendering ---------- */
function draw() {
  ctx.fillStyle = '#0c1116';
  ctx.fillRect(0, 0, SIZE, SIZE);

  ctx.strokeStyle = 'rgba(148,190,178,0.07)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  for (let i = 1; i < N; i++) {
    const p = i * CELL + 0.5;
    ctx.moveTo(p, 0); ctx.lineTo(p, SIZE);
    ctx.moveTo(0, p); ctx.lineTo(SIZE, p);
  }
  ctx.stroke();

  for (let y = 0, i = 0; y < N; y++) {
    for (let x = 0; x < N; x++, i++) {
      const g = ghost[i];
      if (g > 0) {
        ctx.fillStyle = ghostColor(g);
        ctx.fillRect(x * CELL + 1, y * CELL + 1, CELL - 2, CELL - 2);
      }
    }
  }

  for (let y = 0, i = 0; y < N; y++) {
    const r = (y + 1) * PW + 1;
    for (let x = 0; x < N; x++, i++) {
      if (cur[r + x]) {
        ctx.fillStyle = cellColor(age[i]);
        ctx.fillRect(x * CELL + 1, y * CELL + 1, CELL - 2, CELL - 2);
      }
    }
  }

  if (hover) {
    ctx.strokeStyle = 'rgba(255,209,102,0.9)';
    ctx.lineWidth = 1.5;
    ctx.strokeRect(hover.x * CELL + 1.5, hover.y * CELL + 1.5, CELL - 3, CELL - 3);
  }
}

function countPop() {
  let c = 0;
  for (let y = 1; y <= N; y++) {
    const r = y * PW + 1;
    for (let x = 0; x < N; x++) c += cur[r + x];
  }
  return c;
}

function updateStats() {
  const pop = countPop();
  genVal.textContent = gen;
  popVal.textContent = pop;
  hint.classList.toggle('hidden', pop > 0);
}

/* ---------- main loop ---------- */
const intervalMs = () => 600 * Math.pow(0.05, speed.value / 100);  // 600ms .. 30ms

function frame(t) {
  if (playing && t - lastStepT >= intervalMs()) { lastStepT = t; advance(); }
  let trails = false;
  for (let i = 0; i < ghost.length; i++) {
    const g = ghost[i];
    if (g > 0) { const ng = g * 0.86; ghost[i] = ng < 0.012 ? 0 : ng; trails = true; }
  }
  if (needsDraw || trails) { draw(); needsDraw = false; }
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

/* ---------- playback ---------- */
function setPlaying(p) {
  if (p === playing) return;
  playing = p;
  playBtn.classList.toggle('running', p);
  playBtn.setAttribute('aria-pressed', String(p));
  iconPlay.style.display = p ? 'none' : '';
  iconPause.style.display = p ? '' : 'none';
  playLbl.textContent = p ? 'Pause' : 'Run';
  board.classList.toggle('live', p);
  if (p) lastStepT = performance.now();
}

/* ---------- pointer painting ---------- */
function cellFromEvent(e, clampIt) {
  const r = canvas.getBoundingClientRect();
  const x = Math.floor((e.clientX - r.left) / CELL);
  const y = Math.floor((e.clientY - r.top) / CELL);
  if (clampIt) return { x: Math.max(0, Math.min(N - 1, x)), y: Math.max(0, Math.min(N - 1, y)) };
  return (x >= 0 && y >= 0 && x < N && y < N) ? { x, y } : null;
}

function paintLine(a, b) {
  let x0 = a.x, y0 = a.y;
  const x1 = b.x, y1 = b.y;
  const dx = Math.abs(x1 - x0), dy = -Math.abs(y1 - y0);
  const sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1;
  let err = dx + dy;
  for (;;) {
    setCell(x0, y0, paintVal);
    if (x0 === x1 && y0 === y1) break;
    const e2 = 2 * err;
    if (e2 >= dy) { err += dy; x0 += sx; }
    if (e2 <= dx) { err += dx; y0 += sy; }
  }
  updateStats();
}

canvas.addEventListener('pointerdown', e => {
  e.preventDefault();
  const c = cellFromEvent(e, true);
  canvas.setPointerCapture(e.pointerId);
  painting = true;
  paintVal = cur[(c.y + 1) * PW + c.x + 1] ? 0 : 1;   // toggle decides brush mode
  lastCell = c;
  setCell(c.x, c.y, paintVal);
  updateStats();
});

canvas.addEventListener('pointermove', e => {
  const c = cellFromEvent(e, painting);
  if (!c) return;
  if (!hover || hover.x !== c.x || hover.y !== c.y) { hover = c; needsDraw = true; }
  if (painting && lastCell) paintLine(lastCell, c);
  lastCell = c;
});

const endPaint = () => { painting = false; lastCell = null; };
canvas.addEventListener('pointerup', endPaint);
canvas.addEventListener('pointercancel', endPaint);
canvas.addEventListener('pointerleave', () => { if (!painting) { hover = null; needsDraw = true; } });
canvas.addEventListener('contextmenu', e => e.preventDefault());

/* ---------- pattern stamps ---------- */
function parseArt(src) {
  const pts = [];
  src.trim().split('
').forEach((row, y) => {
    [...row].forEach((ch, x) => { if (ch === 'O' || ch === 'o' || ch === '#') pts.push([x, y]); });
  });
  return pts;
}

const ART = {
  Glider: parseArt('.O.
..O
OOO'),
  Spaceship: parseArt('.O..O
O....
O...O
OOOO.'),
  Pulsar: parseArt(
    '..OOO...OOO..
' +
    '.............
' +
    'O....O.O....O
' +
    'O....O.O....O
' +
    'O....O.O....O
' +
    '..OOO...OOO..
' +
    '.............
' +
    '..OOO...OOO..
' +
    'O....O.O....O
' +
    'O....O.O....O
' +
    'O....O.O....O
' +
    '.............
' +
    '..OOO...OOO..'
  ),
  Acorn: parseArt('.O.....
...O...
OO..OOO')
};

function stamp(name) {
  const pts = ART[name];
  if (!pts) return;
  clearBoard();
  const xs = pts.map(p => p[0]), ys = pts.map(p => p[1]);
  const ox = ((N - (Math.max(...xs) - Math.min(...xs) + 1)) >> 1) - Math.min(...xs);
  const oy = ((N - (Math.max(...ys) - Math.min(...ys) + 1)) >> 1) - Math.min(...ys);
  pts.forEach(([x, y]) => setCell(ox + x, oy + y, 1));
  updateStats();
  setPlaying(true);
}

document.querySelectorAll('[data-stamp]').forEach(btn =>
  btn.addEventListener('click', e => { stamp(btn.dataset.stamp); e.currentTarget.blur(); })
);

/* ---------- controls ---------- */
$('step').addEventListener('click', e => { advance(); e.currentTarget.blur(); });
playBtn.addEventListener('click', e => { setPlaying(!playing); e.currentTarget.blur(); });
$('random').addEventListener('click', e => { randomize(); e.currentTarget.blur(); });
$('clear').addEventListener('click', e => { window.life.clear(); e.currentTarget.blur(); });

window.addEventListener('keydown', e => {
  if (e.target && e.target.tagName === 'INPUT') return;
  const k = e.key.toLowerCase();
  if (k === ' ') { e.preventDefault(); setPlaying(!playing); }
  else if (k === 's') advance();
  else if (k === 'r') randomize();
  else if (k === 'c') window.life.clear();
});

/* ---------- programmatic API for grading ---------- */
window.life = {
  get w() { return N; },
  get h() { return N; },
  get(x, y) {
    if (x < 0 || y < 0 || x >= N || y >= N) return 0;
    return cur[(y + 1) * PW + (x + 1)];
  },
  set(x, y, v) { setCell(x, y, v ? 1 : 0); updateStats(); },
  step() { advance(); },
  clear() { clearBoard(); setPlaying(false); }
};

updateStats();
})();
</script>
</body>
</html>
